 class TruckCell extends View {int count,color;String label;Paint p=new Paint(3);TruckCell(int n,int c,String l){super(MainActivity.this);count=n;color=c;label=l;setLayerType(View.LAYER_TYPE_SOFTWARE,null);setClickable(true);setFocusable(true);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),cx=w*.50f,cy=h*.48f;p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(8,18,12));c.drawRoundRect(new RectF(2,2,w-2,h-2),dp(8),dp(8),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(count==0?Color.rgb(27,48,35):color);c.drawRoundRect(new RectF(2,2,w-2,h-2),dp(8),dp(8),p);if(count==0){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(70,92,77));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(11));c.drawText("+",cx,cy+dp(4),p);return;}float tw=Math.min(dp(27),w*.58f),th=Math.min(dp(15),h*.30f),left=cx-tw*.56f,top=cy-th*.58f;p.setStyle(Paint.Style.FILL);p.setColor(color);p.setShadowLayer(dp(7),0,0,color);c.drawRoundRect(new RectF(left,top,left+tw*.62f,top+th),dp(2),dp(2),p);android.graphics.Path cab=new android.graphics.Path();cab.moveTo(left+tw*.62f,top+th*.18f);cab.lineTo(left+tw*.84f,top+th*.18f);cab.lineTo(left+tw,top+th*.55f);cab.lineTo(left+tw,top+th);cab.lineTo(left+tw*.62f,top+th);cab.close();c.drawPath(cab,p);p.clearShadowLayer();p.setColor(Color.rgb(5,10,7));c.drawCircle(left+tw*.24f,top+th+dp(2),dp(3),p);c.drawCircle(left+tw*.82f,top+th+dp(2),dp(3),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(color);c.drawCircle(left+tw*.24f,top+th+dp(2),dp(3),p);c.drawCircle(left+tw*.82f,top+th+dp(2),dp(3),p);p.setStyle(Paint.Style.FILL);p.setColor(Color.WHITE);p.setTextAlign(Paint.Align.CENTER);p.setFakeBoldText(true);p.setTextSize(dp(w<55?8:9));c.drawText(count==1?label:String.valueOf(count),cx,h-dp(5),p);p.setFakeBoldText(false);}}
 int statusColor(String st){if(st.equals("PEDIDO PENDIENTE"))return GREEN;if(st.equals("PROGRAMADO"))return Color.rgb(65,190,235);if(st.equals("EN CURSO"))return YELLOW;if(st.equals("REALIZADO"))return Color.rgb(255,145,60);if(st.equals("REPROGRAMADO"))return Color.rgb(180,105,255);if(st.equals("CANCELADO"))return RED;return WHITE;}
 int dayStatusColor(int r,int d){String[] a=trips(r,d);if(a.length==0)return Color.rgb(58,76,64);HashSet<String>s=new HashSet<>();for(String v:a)s.add(tripState(v));if(s.size()>1)return Color.rgb(180,105,255);return statusColor(tripState(a[0]));}
 int companyStatusColor(int r){HashSet<String>s=new HashSet<>();for(int d=0;d<7;d++)for(String v:trips(r,d))s.add(tripState(v));if(s.isEmpty())return Color.rgb(48,88,65);if(s.size()>1)return Color.rgb(180,105,255);return statusColor(s.iterator().next());}
