 Calendar monday(){Calendar c=(Calendar)week.clone();int d=c.get(Calendar.DAY_OF_WEEK);c.add(Calendar.DATE,d==Calendar.SUNDAY?-6:Calendar.MONDAY-d);return c;}
 String wk(){return new SimpleDateFormat("yyyyMMdd",Locale.US).format(monday().getTime());}
 String key(int row,int day){return wk()+"_"+row+"_"+day;}
 String[] trips(int row,int day){String raw=db.getString(key(row,day),"");return raw.length()==0?new String[0]:raw.split("\\|\\|",-1);}
 String summary(int row,int day){String[] a=trips(row,day);if(a.length==0)return "＋";if(a.length>2){int rea=0,curso=0,otros=0;for(String v:a){String st=tripState(v);if(st.equals("REALIZADO"))rea++;else if(st.equals("EN CURSO"))curso++;else otros++;}return a.length+" VIAJES\n✓ "+rea+"   ▶ "+curso+"   • "+otros+" restantes\nTOCAR PARA VER";}StringBuilder z=new StringBuilder();for(int i=0;i<a.length;i++){if(i>0)z.append("\n────────\n");String v=a[i];String[] p=v.split(" · ");String time=p.length>0?p[0]:"";String service=p.length>1?p[1]:"VIAJE";String st=tripState(v);String state=st.equals("REALIZADO")?"REAL":st.equals("EN CURSO")?"CURSO":st.equals("CANCELADO")?"CANC":st.equals("REPROGRAMADO")?"REPROG":st.equals("PEDIDO PENDIENTE")?"PEND":"PROG";z.append(state).append(" ").append(time).append("\n").append(service);}return z.toString();}
 String tripSummary(String v){String[] p=v.split(" · ");String time=p.length>0?p[0].trim():"";String service=p.length>1?p[1]:"VIAJE";String st=tripState(v);String state=st.equals("REALIZADO")?"✓ REALIZADO":st.equals("EN CURSO")?"▶ EN CURSO":st.equals("CANCELADO")?"× CANCELADO":st.equals("REPROGRAMADO")?"↻ REPROGRAMADO":st.equals("PEDIDO PENDIENTE")?"! PENDIENTE":"• PROGRAMADO";String extra="";for(int i=2;i<p.length;i++){String q=p[i];boolean isState=false;for(String z:states)if(q.equals(z))isState=true;if(!isState&&!q.startsWith("OBS:")){extra=q;break;}}String out=time+" · "+service+"\n"+state;if(extra.length()>0)out+=" · "+(extra.length()>28?extra.substring(0,28)+"…":extra);return out;}
 boolean conflict(int row,int day,String v){return conflictDetail(row,day,v).length()>0;}
 String assignedFrom(String v,String[] catalog){for(String q:catalog)if(q!=null&&!q.startsWith("ELEGIR")&&v.contains(" · "+q+" · "))return q;return "";}
 String conflictDetail(int row,int day,String v){return conflictDetailCore(row,day,v,true);}
 String conflictDetailNew(int row,int day,String v){return conflictDetailCore(row,day,v,false);}
 String conflictDetailCore(int row,int day,String v,boolean skipSelf){String time=tripTime(v);if(!time.matches("\\d{2}:\\d{2}"))return "";String driver=assignedFrom(v,drivers),truck=assignedFrom(v,trucks),trailer=assignedFrom(v,trailers);if(driver.length()==0&&truck.length()==0&&trailer.length()==0)return "";boolean skipped=false;for(int r=0;r<companies.length;r++)for(String x:trips(r,day)){if(skipSelf&&!skipped&&r==row&&x.equals(v)){skipped=true;continue;}if(!tripTime(x).equals(time))continue;String xd=assignedFrom(x,drivers),xt=assignedFrom(x,trucks),xa=assignedFrom(x,trailers);if(driver.length()>0&&driver.equals(xd))return "Chofer "+driver+" ya asignado a "+companies[r]+" a las "+time+".";if(truck.length()>0&&truck.equals(xt))return "Camión "+truck+" ya asignado a "+companies[r]+" a las "+time+".";if(trailer.length()>0&&trailer.equals(xa))return "Acoplado "+trailer+" ya asignado a "+companies[r]+" a las "+time+".";}return "";}
 void appendTrip(int row,int day,String v){String k=key(row,day);ArrayList<String> a=new ArrayList<>(Arrays.asList(trips(row,day)));a.add(v);Collections.sort(a,(x,y)->tripTime(x).compareTo(tripTime(y)));db.edit().putString(k,android.text.TextUtils.join("||",a)).apply();}
 String tripTime(String v){String[] p=v.split(" · ");String t=p.length>0?p[0].trim():"99:99";return t.matches("\\d{2}:\\d{2}")?t:"99:99";}
 void normalizeDay(int row,int day){String[] raw=trips(row,day);ArrayList<String> a=new ArrayList<>(Arrays.asList(raw));Collections.sort(a,(x,y)->tripTime(x).compareTo(tripTime(y)));db.edit().putString(key(row,day),android.text.TextUtils.join("||",a)).apply();}
 void saveHistory(String action,String detail){String old=db.getString("history","");String now=new SimpleDateFormat("dd/MM HH:mm",new Locale("es","AR")).format(new Date());db.edit().putString("history",now+" · "+action+" · "+detail+"\n"+old).apply();}
