 void moveCompanyToPosition(int r,int requested){ArrayList<Integer> a=new ArrayList<>();for(int q:displayOrder())a.add(q);int old=a.indexOf(r);if(old<0)return;int target=Math.max(1,Math.min(requested,a.size()))-1;a.remove(old);a.add(target,r);StringBuilder z=new StringBuilder();for(int q:a){if(z.length()>0)z.append(",");z.append(q);}db.edit().putString("manual_company_order",z.toString()).apply();saveHistory("ORDEN EMPRESA",companies[r]+" · "+(old+1)+" → "+(target+1));render();Toast.makeText(this,companies[r]+" ahora está en posición "+(target+1),Toast.LENGTH_SHORT).show();}
