 void backup(){File dir=new File(getExternalFilesDir(null),"backup");File out=createBackupFile("MANUAL");if(out==null){Toast.makeText(this,"Error de backup",Toast.LENGTH_LONG).show();return;}saveHistory("BACKUP",out.getName());showDark(new AlertDialog.Builder(this).setTitle("BACKUP CREADO").setMessage(out.getName()+"\n\nGuardado en ARCHIVOS > BACKUPS").setPositiveButton("VER BACKUPS",(a,b)->showFiles("BACKUPS · COPIAS COMPLETAS",dir)).setNegativeButton("Cerrar",null));}
 void restoreLatest(){try{File dir=new File(getExternalFilesDir(null),"backup");File[] fs=dir.listFiles();if(fs==null||fs.length==0){Toast.makeText(this,"No hay backups",Toast.LENGTH_SHORT).show();return;}Arrays.sort(fs,(a,b)->Long.compare(b.lastModified(),a.lastModified()));File safety=createBackupFile("ANTES_RESTAURAR");BufferedReader br=new BufferedReader(new InputStreamReader(new FileInputStream(fs[0]),"UTF-8"));SharedPreferences.Editor ed=db.edit().clear();String line;while((line=br.readLine())!=null){int p=line.indexOf('=');if(p>0){String k=line.substring(0,p),v=line.substring(p+1);if(k.startsWith("fav_"))ed.putBoolean(k,Boolean.parseBoolean(v));else ed.putString(k,v);}}br.close();ed.commit();loadCompanies();saveHistory("RESTAURADO",fs[0].getName());render();showDark(new AlertDialog.Builder(this).setTitle("BACKUP RESTAURADO").setMessage("Restaurado: "+fs[0].getName()+"\n\nCopia de seguridad previa: "+(safety==null?"no disponible":safety.getName())).setPositiveButton("OK",null));}catch(Exception e){Toast.makeText(this,"No se pudo restaurar",Toast.LENGTH_LONG).show();}}
 File createBackupFile(String tag){try{File dir=new File(getExternalFilesDir(null),"backup");dir.mkdirs();File out=new File(dir,"FavorableViajes_"+tag+"_"+new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date())+".txt");FileOutputStream os=new FileOutputStream(out);StringBuilder z=new StringBuilder();for(Map.Entry<String,?> e:db.getAll().entrySet())z.append(e.getKey()).append("=").append(String.valueOf(e.getValue())).append("\n");os.write(z.toString().getBytes("UTF-8"));os.close();return out;}catch(Exception e){return null;}}
