 void confirmRestore(){File dir=new File(getExternalFilesDir(null),"backup");File last=latestFile(dir);if(last==null){showDark(new AlertDialog.Builder(this).setTitle("RESTAURAR BACKUP").setMessage("No existe ningún backup local para restaurar.\n\nCreá primero una copia desde ARCHIVOS > BACKUPS.").setPositiveButton("CREAR BACKUP",(a,b)->backup()).setNegativeButton("Cerrar",null));return;}SimpleDateFormat df=new SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("es","AR"));showDark(new AlertDialog.Builder(this).setTitle("RESTAURAR BACKUP").setMessage("Última copia: "+df.format(new Date(last.lastModified()))+"\n"+last.getName()+"\n\nLa restauración reemplazará los datos actuales. ¿Continuar?").setPositiveButton("RESTAURAR",(a,b)->restoreLatest()).setNegativeButton("Cancelar",null));}
 void integrityAudit(){int total=0,active=0,sinHora=0,sinChofer=0,sinCamion=0,sinBackup=fileCount(new File(getExternalFilesDir(null),"backup"))==0?1:0;ArrayList<String> issues=new ArrayList<>();for(int r=0;r<companies.length;r++)for(int d=0;d<7;d++)for(String v:trips(r,d)){total++;if(tripState(v).equals("CANCELADO"))continue;active++;boolean bad=false;StringBuilder z=new StringBuilder();if(tripTime(v).equals("99:99")){sinHora++;bad=true;z.append("SIN HORA ");}if(assignedFrom(v,drivers).length()==0){sinChofer++;bad=true;z.append("SIN CHOFER ");}if(assignedFrom(v,trucks).length()==0){sinCamion++;bad=true;z.append("SIN CAMIÓN ");}if(bad)issues.add(companies[r]+" · "+dayLong[d]+" · "+z.toString().trim());}String msg="Viajes totales: "+total+"\nViajes activos: "+active+"\nSin hora: "+sinHora+"\nSin chofer: "+sinChofer+"\nSin camión: "+sinCamion+"\n"+backupHealth()+"\n\n"+((sinHora+sinChofer+sinCamion+sinBackup)==0?"INTEGRIDAD OPERATIVA OK":"REVISAR "+issues.size()+" VIAJE(S)");if(!issues.isEmpty()){StringBuilder z=new StringBuilder(msg+"\n\n");int max=Math.min(issues.size(),12);for(int i=0;i<max;i++)z.append("• ").append(issues.get(i)).append("\n");if(issues.size()>max)z.append("… y ").append(issues.size()-max).append(" más");msg=z.toString();}showDark(new AlertDialog.Builder(this).setTitle("AUDITORÍA DE INTEGRIDAD").setMessage(msg).setPositiveButton("VER SIN ASIGNAR",(a,b)->unassignedTrips()).setNeutralButton("ARCHIVOS",(a,b)->openExportFolder()).setNegativeButton("Cerrar",null));}
 void diagnostics(){int tripCount=0,ev=0,conflicts=0;for(int r=0;r<companies.length;r++)for(int d=0;d<7;d++){String[] a=trips(r,d);tripCount+=a.length;for(int j=0;j<a.length;j++){String raw=db.getString(evidenceKey(r,d,j),"");if(raw.length()>0)ev+=raw.split("\\|\\|").length;if(conflictDetail(r,d,a[j]).length()>0)conflicts++;}}conflicts=conflicts/2;File bd=new File(getExternalFilesDir(null),"backup");File pd=new File(getExternalFilesDir(null),"pdf");File xd=new File(getExternalFilesDir(null),"exportados");int backups=fileCount(bd),pdfs=fileCount(pd),exports=fileCount(xd);String status=conflicts==0?"OPERATIVO · SIN CONFLICTOS":"ATENCIÓN · "+conflicts+" CONFLICTO(S)";String storage=backupHealth()+" · "+pdfs+" PDF · "+exports+" EXPORTADO(S)";showDark(new AlertDialog.Builder(this).setTitle("DIAGNÓSTICO FAVORABLE VIAJES").setMessage("Semana: "+wk()+"\\nEmpresas: "+companies.length+"\\nViajes cargados: "+tripCount+"\\nEvidencias vinculadas: "+ev+"\\nConflictos de recursos: "+conflicts+"\\nBackups locales: "+backups+"\\nPDF generados: "+pdfs+"\\nExportados: "+exports+"\\nProtección de datos: "+storage+"\\n\\nEstado local: "+status).setPositiveButton("Cerrar",null));}
 void weekMovementSummary(){LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(LinearLayout.VERTICAL);wrap.setPadding(dp(6),dp(6),dp(6),dp(6));int sw=widthDpSafe();int cw=Math.max(90,sw/4),dw=Math.max(46,(sw-cw-28)/5);LinearLayout head=new LinearLayout(this);TextView he=tx("EMPRESA",9,GREEN);he.setGravity(Gravity.CENTER);head.addView(he,new LinearLayout.LayoutParams(dp(cw),dp(42)));Calendar mm=monday();for(int d=0;d<5;d++){Calendar z=(Calendar)mm.clone();z.add(Calendar.DATE,d);TextView h=tx(days[d]+"\n"+new SimpleDateFormat("dd",Locale.US).format(z.getTime()),8,GREEN);h.setGravity(Gravity.CENTER);h.setBackground(shape(PANEL,dp(6)));head.addView(h,new LinearLayout.LayoutParams(dp(dw),dp(42)));}wrap.addView(head);int moved=0,total=0;for(int r:displayOrder()){int monFri=0;for(int d=0;d<5;d++)monFri+=trips(r,d).length;if(monFri==0)continue;moved++;total+=monFri;final int rr=r;LinearLayout row=new LinearLayout(this);TextView name=tx((db.getBoolean("fav_"+r,false)?"★ ":"")+companies[r],8,WHITE);name.setGravity(Gravity.CENTER_VERTICAL);GradientDrawable nbg=shape(Color.rgb(12,38,22),dp(6));nbg.setStroke(dp(2),companyStatusColor(r));name.setBackground(nbg);name.setOnClickListener(v->companyTrips(rr));row.addView(name,new LinearLayout.LayoutParams(dp(cw),dp(58)));for(int d=0;d<5;d++){String[] aa=trips(r,d);final int dd=d;TruckCell cell=truckCell(rr,d);cell.setContentDescription(companies[rr]+" · "+days[d]+" · "+aa.length+" viajes");cell.setOnClickListener(v->{if(trips(rr,dd).length==0)form(companies[rr],dd,rr);else companyDayTrips(rr,dd);});row.addView(cell,new LinearLayout.LayoutParams(dp(dw),dp(58)));}wrap.addView(row);}if(moved==0)wrap.addView(tx("No hubo movimiento de lunes a viernes.",13,MUTED));HorizontalScrollView hs=new HorizontalScrollView(this);hs.addView(wrap);ScrollView vs=new ScrollView(this);vs.addView(hs);AlertDialog wd=new AlertDialog.Builder(this).setTitle("SEMANA · LUNES A VIERNES · "+moved+" EMPRESAS · "+total+" VIAJES").setView(vs).setPositiveButton("Cerrar",null).create();wd.setOnShowListener(x->darkDialog(wd));wd.show();}
