 void stateTripsMenu(){String[] opts={"PEDIDO PENDIENTE","PROGRAMADO","EN CURSO","REALIZADO","REPROGRAMADO","CANCELADO"};showDark(new AlertDialog.Builder(this).setTitle("VIAJES POR ESTADO").setItems(opts,(a,n)->{String st=opts[n];showDark(new AlertDialog.Builder(this).setTitle(st).setItems(new String[]{"HOY / DÍA","SEMANA COMPLETA"},(b,k)->{if(k==0)chooseStateDay(st);else showTripsByState(st,-1);}).setNegativeButton("Volver",null));}).setNegativeButton("Cerrar",null));}
