 void showTripsByState(String st,int onlyDay){ArrayList<String> items=new ArrayList<>();ArrayList<int[]> refs=new ArrayList<>();for(int d=0;d<7;d++){if(onlyDay>=0&&d!=onlyDay)continue;for(int r:displayOrder()){String[] aa=trips(r,d);for(int j=0;j<aa.length;j++){String v=aa[j];if(tripState(v).equals(st)){items.add(dayLong[d]+" · "+companies[r]+" · "+(tripTime(v).equals("99:99")?"SIN HORA":tripTime(v))+"\n"+tripSummary(v));refs.add(new int[]{r,d,j});}}}}String scope=onlyDay>=0?dayLong[onlyDay]:"SEMANA COMPLETA";if(items.isEmpty()){showDark(new AlertDialog.Builder(this).setTitle(st+" · "+scope).setMessage("No hay viajes con este estado.").setPositiveButton("Cerrar",null));return;}showDark(new AlertDialog.Builder(this).setTitle(st+" · "+scope+" · "+items.size()+" VIAJE(S)").setItems(items.toArray(new String[0]),(x,n)->{int[] z=refs.get(n);detail(z[0],z[1],z[2],trips(z[0],z[1])[z[2]]);}).setNegativeButton("Cerrar",null));}
