 void resources(){int driversUsed=0,trucksUsed=0;HashSet<String> ds=new HashSet<>(),ts=new HashSet<>();for(int r=0;r<companies.length;r++)for(int d=0;d<7;d++)for(String v:trips(r,d)){for(String q:drivers)if(!q.startsWith("ELEGIR")&&v.contains(q))ds.add(q);for(String q:trucks)if(!q.startsWith("ELEGIR")&&v.contains(q))ts.add(q);}driversUsed=ds.size();trucksUsed=ts.size();int sinD=0,sinT=0;for(int r=0;r<companies.length;r++)for(int d=0;d<7;d++)for(String v:trips(r,d)){if(tripState(v).equals("CANCELADO"))continue;boolean hd=false,ht=false;for(String q:drivers)if(!q.startsWith("ELEGIR")&&v.contains(q))hd=true;for(String q:trucks)if(!q.startsWith("ELEGIR")&&v.contains(q))ht=true;if(!hd)sinD++;if(!ht)sinT++;}showDark(new AlertDialog.Builder(this).setTitle("RECURSOS · SEMANA").setMessage("Choferes utilizados: "+driversUsed+" / "+(drivers.length-1)+"\nCamiones utilizados: "+trucksUsed+" / "+trucks.length+"\nViajes sin chofer: "+sinD+"\nViajes sin camión: "+sinT+"\nAcoplados disponibles: "+(trailers.length-1)+"\nContenedores catalogados: 5").setPositiveButton("VER SIN ASIGNAR",(a,b)->unassignedTrips()).setNegativeButton("Cerrar",null));}
 void unassignedTrips(){ArrayList<String> items=new ArrayList<>();ArrayList<int[]> refs=new ArrayList<>();for(int r=0;r<companies.length;r++)for(int d=0;d<7;d++){String[] aa=trips(r,d);for(int j=0;j<aa.length;j++){String v=aa[j];if(tripState(v).equals("CANCELADO"))continue;boolean hd=false,ht=false;for(String q:drivers)if(!q.startsWith("ELEGIR")&&v.contains(q))hd=true;for(String q:trucks)if(!q.startsWith("ELEGIR")&&v.contains(q))ht=true;if(!hd||!ht){items.add(companies[r]+" · "+dayLong[d]+" · "+tripTime(v)+"\n"+(!hd?"SIN CHOFER":"CHOFER OK")+" · "+(!ht?"SIN CAMIÓN":"CAMIÓN OK"));refs.add(new int[]{r,d,j});}}}if(items.isEmpty()){showDark(new AlertDialog.Builder(this).setTitle("SIN ASIGNAR").setMessage("Todos los viajes activos tienen chofer y camión asignados.").setPositiveButton("Cerrar",null));return;}showDark(new AlertDialog.Builder(this).setTitle("VIAJES SIN ASIGNAR · "+items.size()).setItems(items.toArray(new String[0]),(x,n)->{int[] z=refs.get(n);detail(z[0],z[1],z[2],trips(z[0],z[1])[z[2]]);}).setNegativeButton("Cerrar",null));}
