 void stats(){int total=0,rea=0,prog=0,curso=0,repro=0,canc=0,ped=0,retiros=0,servicios=0,mixtos=0,sinHora=0;double kgBruto=0,kgTara=0,kgNeto=0;int[] daily=new int[7];HashMap<String,Integer> matCount=new HashMap<>(),serviceCount=new HashMap<>(),matDone=new HashMap<>(),serviceDone=new HashMap<>(),driverCount=new HashMap<>(),truckCount=new HashMap<>(),companyCount=new HashMap<>(),destCount=new HashMap<>();for(int r=0;r<companies.length;r++)for(int d=0;d<7;d++)for(String v:trips(r,d)){total++;daily[d]++;companyCount.put(companies[r],companyCount.containsKey(companies[r])?companyCount.get(companies[r])+1:1);String st=tripState(v);if(st.equals("REALIZADO"))rea++;else if(st.equals("EN CURSO"))curso++;else if(st.equals("REPROGRAMADO"))repro++;else if(st.equals("CANCELADO"))canc++;else if(st.equals("PEDIDO PENDIENTE"))ped++;else prog++;if(v.contains("RETIRO + SERVICIO"))mixtos++;else if(v.contains("RETIRO DE MATERIALES"))retiros++;else if(v.contains("SERVICIO DE RETIRO"))servicios++;if(tripTime(v).equals("99:99"))sinHora++;kgBruto+=numField(v,"BRUTO");kgTara+=numField(v,"TARA");kgNeto+=numField(v,"NETO");for(String q:materials)if(v.contains(q)){matCount.put(q,matCount.containsKey(q)?matCount.get(q)+1:1);if(tripState(v).equals("REALIZADO"))matDone.put(q,matDone.containsKey(q)?matDone.get(q)+1:1);}for(String q:new String[]{"LINNER","FLEJES","RSU","OTRO"})if(v.contains(" · "+q)){serviceCount.put(q,serviceCount.containsKey(q)?serviceCount.get(q)+1:1);if(tripState(v).equals("REALIZADO"))serviceDone.put(q,serviceDone.containsKey(q)?serviceDone.get(q)+1:1);}for(String q:drivers)if(!q.startsWith("ELEGIR")&&v.contains(q))driverCount.put(q,driverCount.containsKey(q)?driverCount.get(q)+1:1);for(String q:trucks)if(!q.startsWith("ELEGIR")&&v.contains(q))truckCount.put(q,truckCount.containsKey(q)?truckCount.get(q)+1:1);for(String q:destinations)if(v.contains(q))destCount.put(q,destCount.containsKey(q)?destCount.get(q)+1:1);}ScrollView sv=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),dp(8),dp(12),dp(18));sv.addView(box);int completePct=total==0?0:Math.round(100f*(total-sinHora)/total);TextView kpi=tx("VIAJES  "+total+"     REALIZADOS  "+rea+"     PENDIENTES  "+ped+"\nEN CURSO  "+curso+"     REPROGRAMADOS  "+repro+"     CANCELADOS  "+canc+"\nPROGRAMACIÓN CON HORA  "+completePct+"%     ·     SIN HORA  "+sinHora,12,WHITE);kpi.setPadding(dp(12),dp(12),dp(12),dp(12));GradientDrawable kgp=shape(Color.rgb(9,25,16),dp(12));kgp.setStroke(dp(1),GREEN);kpi.setBackground(kgp);box.addView(kpi);box.addView(section("TRÁFICO SEMANAL · LUNES A DOMINGO"));box.addView(barChart(days,daily));int pico=0,picoDia=0;for(int i=0;i<7;i++)if(daily[i]>pico){pico=daily[i];picoDia=i;}int laborables=0,finde=0;for(int i=0;i<5;i++)laborables+=daily[i];finde=daily[5]+daily[6];int trafProm=Math.round(total/7f);TextView traf=tx("TOTAL SEMANAL  "+total+" VIAJES   ·   PROMEDIO  "+trafProm+"/DÍA\nDÍA DE MAYOR TRÁFICO  "+(total==0?"—":days[picoDia]+" · "+pico+" VIAJES")+"\nLUNES A VIERNES  "+laborables+"   ·   FIN DE SEMANA  "+finde,11,WHITE);traf.setPadding(dp(12),dp(10),dp(12),dp(10));traf.setBackground(shape(PANEL,dp(10)));box.addView(traf);box.addView(section("TIPO DE OPERACIÓN"));box.addView(barChart(new String[]{"RETIRO","SERVICIO","AMBOS"},new int[]{retiros,servicios,mixtos}));box.addView(section("ESTADO DE VIAJES"));box.addView(barChart(new String[]{"REAL.","CURSO","PROG.","PEND.","REPRO.","CANC."},new int[]{rea,curso,prog,ped,repro,canc}));box.addView(section("EMPRESAS CON MÁS MOVIMIENTO"));box.addView(rankingView(companyCount,8));box.addView(section("KILOS REGISTRADOS EN LA SEMANA"));TextView kg=tx("BRUTO  "+fmtKg(kgBruto)+" KG   ·   TARA  "+fmtKg(kgTara)+" KG\nNETO  "+fmtKg(kgNeto)+" KG",13,WHITE);kg.setPadding(dp(12),dp(10),dp(12),dp(10));kg.setBackground(shape(PANEL,dp(10)));box.addView(kg);box.addView(section("MATERIALES REALIZADOS EN LA SEMANA"));box.addView(rankingView(matDone,12));box.addView(section("SERVICIOS REALIZADOS EN LA SEMANA"));box.addView(rankingView(serviceDone,12));box.addView(section("CHOFERES CON MÁS VIAJES"));box.addView(rankingView(driverCount,8));box.addView(section("CAMIONES CON MÁS VIAJES"));box.addView(rankingView(truckCount,8));box.addView(section("DESTINOS MÁS UTILIZADOS"));box.addView(rankingView(destCount,8));box.addView(section("INDICADORES DE GESTIÓN"));int activos=Math.max(0,total-canc);int cumplimiento=activos==0?0:Math.round(100f*rea/activos);int pendientesOperativos=ped+repro+sinHora;int cargaRecursos=total==0?0:Math.round(100f*(total-sinHora)/total);int promedioDia=Math.round(total/7f);TextView ind=tx("CUMPLIMIENTO DE VIAJES  "+cumplimiento+"%\nVIAJES ACTIVOS  "+activos+"   ·   PROMEDIO/DÍA  "+promedioDia+"\nPENDIENTES / REPROGRAMADOS / SIN HORA  "+pendientesOperativos+"\nPROGRAMACIÓN DEFINIDA  "+cargaRecursos+"%\nEMPRESAS ATENDIDAS  "+companyCount.size()+"\nCHOFERES UTILIZADOS  "+driverCount.size()+"   ·   CAMIONES UTILIZADOS  "+truckCount.size()+"\nMATERIALES CON MOVIMIENTO  "+matCount.size(),11,WHITE);ind.setPadding(dp(12),dp(10),dp(12),dp(10));ind.setBackground(shape(PANEL,dp(10)));box.addView(ind);box.addView(section("CONCENTRACIÓN DE ACTIVIDAD"));ArrayList<Map.Entry<String,Integer>> cc=new ArrayList<>(companyCount.entrySet());Collections.sort(cc,(x,y)->Integer.compare(y.getValue(),x.getValue()));int top3=0;for(int i=0;i<Math.min(3,cc.size());i++)top3+=cc.get(i).getValue();int top3pct=total==0?0:Math.round(100f*top3/total);TextView conc=tx("TOP 3 EMPRESAS CONCENTRAN  "+top3pct+"%  DE LOS VIAJES\nEMPRESAS CON MOVIMIENTO  "+companyCount.size()+"   ·   VIAJES/EMPRESA  "+(companyCount.size()==0?0:Math.round(total/(float)companyCount.size())),11,WHITE);conc.setPadding(dp(12),dp(10),dp(12),dp(10));conc.setBackground(shape(PANEL,dp(10)));box.addView(conc);box.addView(section("DISTRIBUCIÓN OPERATIVA"));int opTotal=retiros+servicios+mixtos;int pr=opTotal==0?0:Math.round(100f*retiros/opTotal),ps=opTotal==0?0:Math.round(100f*servicios/opTotal),pm=opTotal==0?0:Math.max(0,100-pr-ps);TextView mix=tx("RETIROS  "+pr+"%   ·   SERVICIOS  "+ps+"%   ·   AMBOS  "+pm+"%\nREALIZADOS SOBRE ACTIVOS  "+cumplimiento+"%   ·   CANCELADOS  "+(total==0?0:Math.round(100f*canc/total))+"%",11,WHITE);mix.setPadding(dp(12),dp(10),dp(12),dp(10));mix.setBackground(shape(PANEL,dp(10)));box.addView(mix);box.addView(section("ALERTAS DE GESTIÓN"));StringBuilder al=new StringBuilder();if(sinHora>0)al.append("• ").append(sinHora).append(" viaje(s) sin horario\n");if(ped>0)al.append("• ").append(ped).append(" pedido(s) pendiente(s)\n");if(repro>0)al.append("• ").append(repro).append(" viaje(s) reprogramado(s)\n");if(canc>0)al.append("• ").append(canc).append(" cancelación(es)\n");if(al.length()==0)al.append("Sin alertas operativas en la semana");TextView alert=tx(al.toString(),11,al.toString().startsWith("Sin")?GREEN:YELLOW);alert.setPadding(dp(12),dp(10),dp(12),dp(10));alert.setBackground(shape(PANEL2,dp(10)));box.addView(alert);AlertDialog sd=new AlertDialog.Builder(this).setTitle("ESTADÍSTICAS PRO · "+weekTitle.getText()).setView(sv).setPositiveButton("EXPORTAR PDF",(a,b)->exportStatsPdf()).setNeutralButton("EXPORTAR EXCEL",(a,b)->exportStatsExcel()).setNegativeButton("Cerrar",null).create();sd.setOnShowListener(x->darkDialog(sd));sd.show();}
 void exportStatsExcel(){try{File dir=new File(getExternalFilesDir(null),"exportados");dir.mkdirs();Calendar m=monday(),sun=(Calendar)m.clone();sun.add(Calendar.DATE,6);String stamp=new SimpleDateFormat("yyyyMMdd",Locale.US).format(m.getTime());File out=new File(dir,"Favorable_Estadisticas_"+stamp+".xls");StringBuilder z=new StringBuilder();z.append("FAVORABLE - ESTADISTICAS SEMANALES\n");z.append("SEMANA\t").append(new SimpleDateFormat("dd/MM/yyyy",new Locale("es","AR")).format(m.getTime())).append(" AL ").append(new SimpleDateFormat("dd/MM/yyyy",new Locale("es","AR")).format(sun.getTime())).append("\n\n");z.append("DIA\tEMPRESA\tESTADO\tHORA\tOPERACION\tBRUTO_KG\tTARA_KG\tNETO_KG\n");for(int d=0;d<7;d++)for(int r:displayOrder())for(String v:trips(r,d))z.append(dayLong[d]).append("\t").append(companies[r].replace("\t"," ")).append("\t").append(tripState(v)).append("\t").append(tripTime(v).equals("99:99")?"":tripTime(v)).append("\t").append(tripSummary(v).replace("\t"," ")).append("\t").append(fieldValue(v,"BRUTO")).append("\t").append(fieldValue(v,"TARA")).append("\t").append(fieldValue(v,"NETO")).append("\n");FileOutputStream os=new FileOutputStream(out);os.write(z.toString().getBytes("UTF-8"));os.close();saveHistory("ESTADÍSTICAS EXCEL",out.getName());showDark(new AlertDialog.Builder(this).setTitle("ESTADÍSTICAS EXPORTADAS · EXCEL").setMessage("Guardado en ARCHIVOS > EXPORTADOS\n\n"+out.getName()).setPositiveButton("COMPARTIR",(a,b)->shareFile(out,"application/vnd.ms-excel","Compartir estadísticas")).setNeutralButton("ARCHIVOS",(a,b)->openExportFolder()).setNegativeButton("Cerrar",null));}catch(Exception e){Toast.makeText(this,"No se pudo exportar estadísticas a Excel",Toast.LENGTH_LONG).show();}}
 void exportStatsPdf(){try{int total=0;HashMap<String,Integer> states=new HashMap<>();int[] daily=new int[7];double bruto=0,tara=0,neto=0;for(int d=0;d<7;d++)for(int r=0;r<companies.length;r++)for(String v:trips(r,d)){total++;daily[d]++;String st=tripState(v);states.put(st,states.containsKey(st)?states.get(st)+1:1);bruto+=numField(v,"BRUTO");tara+=numField(v,"TARA");neto+=numField(v,"NETO");}Calendar m=monday(),sun=(Calendar)m.clone();sun.add(Calendar.DATE,6);SimpleDateFormat df=new SimpleDateFormat("dd/MM/yyyy",new Locale("es","AR"));PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());android.graphics.Canvas c=page.getCanvas();Paint pnt=new Paint();pnt.setColor(Color.rgb(18,70,42));c.drawRect(0,0,595,76,pnt);pnt.setColor(Color.WHITE);pnt.setTextSize(22);pnt.setFakeBoldText(true);c.drawText("FAVORABLE · ESTADÍSTICAS",28,36,pnt);pnt.setTextSize(11);pnt.setFakeBoldText(false);c.drawText("SEMANA "+df.format(m.getTime())+" AL "+df.format(sun.getTime()),28,58,pnt);pnt.setColor(Color.DKGRAY);pnt.setTextSize(15);pnt.setFakeBoldText(true);c.drawText("RESUMEN DE ESTADOS",28,112,pnt);int y=140;String[] sts={"PEDIDO PENDIENTE","PROGRAMADO","EN CURSO","REALIZADO","REPROGRAMADO","CANCELADO"};for(String st:sts){pnt.setTextSize(12);pnt.setFakeBoldText(false);c.drawText(st+"  "+(states.containsKey(st)?states.get(st):0),36,y,pnt);y+=24;}pnt.setFakeBoldText(true);c.drawText("TOTAL VIAJES  "+total,36,y+8,pnt);y+=52;c.drawText("TRÁFICO POR DÍA",28,y,pnt);y+=28;pnt.setFakeBoldText(false);for(int d=0;d<7;d++){c.drawText(dayLong[d]+"  "+daily[d],36,y,pnt);y+=22;}y+=18;pnt.setFakeBoldText(true);c.drawText("KILOS REGISTRADOS",28,y,pnt);y+=28;pnt.setFakeBoldText(false);c.drawText("BRUTO  "+fmtKg(bruto)+" KG    TARA  "+fmtKg(tara)+" KG    NETO  "+fmtKg(neto)+" KG",36,y,pnt);y+=42;pnt.setTextSize(10);pnt.setColor(Color.GRAY);c.drawText("Generado "+new SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("es","AR")).format(new Date()),28,810,pnt);pdf.finishPage(page);File dir=new File(getExternalFilesDir(null),"pdf");dir.mkdirs();File out=new File(dir,"Favorable_Estadisticas_"+new SimpleDateFormat("yyyyMMdd",Locale.US).format(m.getTime())+".pdf");FileOutputStream os=new FileOutputStream(out);pdf.writeTo(os);os.close();pdf.close();saveHistory("ESTADÍSTICAS PDF",out.getName());showDark(new AlertDialog.Builder(this).setTitle("ESTADÍSTICAS EXPORTADAS · PDF").setMessage("Guardado en ARCHIVOS > PDF\n\n"+out.getName()).setPositiveButton("COMPARTIR",(a,b)->shareFile(out,"application/pdf","Compartir estadísticas")).setNeutralButton("ARCHIVOS",(a,b)->openExportFolder()).setNegativeButton("Cerrar",null));}catch(Exception e){Toast.makeText(this,"No se pudo exportar estadísticas a PDF",Toast.LENGTH_LONG).show();}}
 double numField(String v,String k){try{String q=fieldValue(v,k).replace(",",".").trim();return q.length()==0?0:Double.parseDouble(q);}catch(Exception e){return 0;}}
 String fmtKg(double n){return n==Math.rint(n)?String.valueOf((long)n):String.format(new Locale("es","AR"),"%.2f",n);}
 TextView section(String t){TextView v=tx(t,11,YELLOW);v.setTypeface(null,1);v.setPadding(dp(10),dp(12),dp(10),dp(7));GradientDrawable g=shape(Color.rgb(10,26,17),dp(8));g.setStroke(dp(1),Color.rgb(55,82,62));v.setBackground(g);return v;}
 View barChart(String[] names,int[] vals){LinearLayout chart=new LinearLayout(this);chart.setOrientation(LinearLayout.VERTICAL);int max=1;for(int v:vals)if(v>max)max=v;for(int i=0;i<names.length;i++){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView n=tx(names[i],9,WHITE);row.addView(n,new LinearLayout.LayoutParams(dp(72),dp(30)));LinearLayout track=new LinearLayout(this);track.setBackground(shape(Color.rgb(7,18,11),dp(6)));LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,dp(14),1);row.addView(track,tp);TextView fill=new TextView(this);GradientDrawable fg=shape(Color.rgb(65,190,85),dp(6));fg.setStroke(dp(1),GREEN);fill.setBackground(fg);track.addView(fill,new LinearLayout.LayoutParams(0,-1,vals[i]));if(vals[i]<max)track.addView(new Space(this),new LinearLayout.LayoutParams(0,-1,max-vals[i]));TextView num=tx(""+vals[i],10,WHITE);num.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);row.addView(num,new LinearLayout.LayoutParams(dp(34),dp(30)));chart.addView(row);}return chart;}
 View rankingView(HashMap<String,Integer> map,int maxRows){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);ArrayList<Map.Entry<String,Integer>> a=new ArrayList<>(map.entrySet());Collections.sort(a,(x,y)->Integer.compare(y.getValue(),x.getValue()));if(a.isEmpty()){box.addView(tx("Sin datos",10,MUTED));return box;}int mx=a.get(0).getValue();for(int i=0;i<Math.min(maxRows,a.size());i++){Map.Entry<String,Integer> e=a.get(i);LinearLayout row=new LinearLayout(this);TextView n=tx((i+1)+". "+e.getKey(),9,WHITE);row.addView(n,new LinearLayout.LayoutParams(0,dp(28),1));TextView v=tx(""+e.getValue(),10,YELLOW);v.setTypeface(null,1);row.addView(v,new LinearLayout.LayoutParams(dp(38),dp(28)));box.addView(row);}return box;}
 void appendTop(StringBuilder m,HashMap<String,Integer> map,int max){ArrayList<Map.Entry<String,Integer>> a=new ArrayList<>(map.entrySet());Collections.sort(a,(x,y)->Integer.compare(y.getValue(),x.getValue()));if(a.isEmpty()){m.append("Sin datos\n");return;}for(int i=0;i<Math.min(max,a.size());i++)m.append(i+1).append(". ").append(a.get(i).getKey()).append(" · ").append(a.get(i).getValue()).append("\n");}
